package com.andye.warmod.radar.client.gui;import com.andye.warmod.radar.client.ClientRadarInterception;import net.minecraft.client.gui.GuiGraphicsExtractor;public final class RadarInterceptionRenderer{private RadarInterceptionRenderer(){}public static void render(GuiGraphicsExtractor g,ClientRadarInterception e,RadarMapTransform t,double now,int left,int top,int width,int height){double age=e.age(now),alpha=Math.max(0,1-age/80.0),radius=(4+age*.45);int x=(int)Math.round(t.screenX(e.payload().position().x,left,width)),y=(int)Math.round(t.screenY(e.payload().position().z,top,height));int color=((int)(255*alpha)<<24)|0x55e7ff;RadarPolylineRenderer.drawRing(g,x,y,radius,left,top,width,height,color,2,48);if(age<30)g.text(net.minecraft.client.Minecraft.getInstance().font,net.minecraft.network.chat.Component.literal("INTERCEPT"),x+6,y-6,color);}}